import React, { useEffect, useState, useRef } from "react";

import { getStore, updStore, gen16CodeId, parseDate, fetchPostH, getUrlServerSide, ObjectKeys, hasWritePrivilege, parseDateMMDDYYYY, qryKClient, b64toUrl, getExtFileType } from "../../../stores/Utils";

import "./dashboard.css"
import {  UpdFeedfromMobile_Cmpt, MovementUpdateRv_Cmpt } from "..";
import { OpenModal } from "../../../components/DialogHRM";
import { getall_feedfMbl, sort_feedfMbl, delete_feedfMbl, handleFetchImage, handleDetectLandMark, handleFetchImageComp } from "../services/server_fetching";
import { SvgIcon_Cmpt, LoadingColorSpinner_Cmpt } from "../../../components";
import DeleteAlert from "./deleteAlert";
import FeedfromMobileComprobante from "./RegComprobanteFeedfromMobile";
import { useNavigate } from "react-router";
import { TextOnImage_Cmpt } from "../../PhotoComponent";
import { NavLink } from "react-router-dom";

const Svg = SvgIcon_Cmpt();

const UpdFeedfromMobile = UpdFeedfromMobile_Cmpt();



const MovementUpdateRv = MovementUpdateRv_Cmpt();




const FeedfromMobileItem  = ({ data, elmId, handleRefreshAll }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);
	const navigate = useNavigate();

	const [loadingAmount, set_loadingAmount] = useState(0);

	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			
			// let frm2 = {"firstName":"Belisario","lastName":"Gonzalez Arevalo","genre":"Male","dateOfBirth":"06/02/1976","placeOfBirth":{"city":"Holguin","state":"Holguin"},"currentAddress":{"No":"4307","street":"Estate Dr","city":"Louisville","state":"Kentucky","zipcode":"40216"},"dob":202536000000}
			//updStore(frmNm, frm2);
			set_obs(gen16CodeId())
		}
	});

	
	const updObs =  () => {
		set_obs(gen16CodeId())
	}

	
	const refreshAccs =  () => {
		getall_feedfMbl(updObs);
	}

	const update = async () => {
		if(hasWritePrivilege()){
			updStore("upd_fromMobile", data);
			updStore("upd_fromMobile_bck", JSON.parse(JSON.stringify(data)));
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "80vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true };
			modaldata["content"] = <UpdFeedfromMobile confirm={refreshAccs} />;
			OpenModal(modaldata);
		}
	}


	const deleteComprobante =  () => {
		delete_feedfMbl(data?.movementId, handleRefreshAll);
	}
	

	const OpenDeleteAlert =  () => {
		let lastTimeCallModal = getStore("lastTimeCallModal") || 0;
		if(Date.now() > lastTimeCallModal){
			updStore("lastTimeCallModal", Date.now()+320);
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "40vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
			modaldata["content"] = <DeleteAlert confirm={deleteComprobante} item={data} />
			OpenModal(modaldata);
		}
	}




	const validateImage = (result) => {
		
		var i = new Image();	
		i.onload = function(){
			let dmzImg = {
				oh: i.height,
				ow: i.width,
				h: i.height,
				w: i.width,
			}
			updStore( "preview_mov_dmz",dmzImg);
			openUpdView();
		};
		if(result){
			i.src = result;
		}
	}	

	const openImage =  (imagePath) => {
		let extTp = getExtFileType(imagePath);
		handleFetchImage(getStore("profileUser")?.businessId,imagePath, (v)=>openImageCb(v,extTp));
	}


	const openImageCb = async (v,ext) => {
		var blob = await b64toUrl(v, ext);
		updStore("image_url_mov",v);
		updStore("image_preview_mov",blob);
		validateImage(blob);
	}
	
	const openUpdView =  (v,ext) => {
		let modaldata = {};
		//updStore("cmp_feedfromMobile", data);
		modaldata["zIndex"] = 450;
		modaldata["height"] = "80vh";
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true };
		modaldata["content"] = <MovementUpdateRv confirm={handleRefreshAll} item={data} />;
		OpenModal(modaldata);
	}


	const openLinkCmp = async () => {
		if(hasWritePrivilege()){
			if(data.inManualRevision ){
				updStore(qryKClient()+"_upd", data);
				updStore(qryKClient()+"_upd_bck", JSON.parse(JSON.stringify(data)));
				openImage(data.imagePath)
				
			}
			else if(data.comprobanteId){
				let url = window.location.origin +`/#/accounting-ledger?cId=${data.comprobanteId}`;
				window.open(url)

			}else{
				let modaldata = {};
				//updStore("cmp_feedfromMobile", data);
				modaldata["zIndex"] = 450;
				modaldata["height"] = "80vh";
				// data['observeResize']=true;
				modaldata["props"] = { minHeight: "1vh", overlay: true };
				modaldata["content"] = <FeedfromMobileComprobante confirm={handleRefreshAll} item={data} />;
				OpenModal(modaldata);
			}
		}
	}


	const Image2Resize = async () => {
		let imagePathWp = data.imagePath;
		let extTp = getExtFileType(imagePathWp);
		handleFetchImage(imagePathWp, (v)=>handleFetchImageComp(v,imagePathWp));
	}


	

	

	const open2ImageCb = async (v, ext) => {
		if(v){
			var blob = await b64toUrl(v, ext);
			window.open(blob)
		}
		else{
			Image2Resize()
		}
	}


	const open2Image =  () => {
		let imagePathWp = data.imagePath;
		imagePathWp = data.imagePath.split(".png")[0]+".webp";
		let extTp = getExtFileType(imagePathWp);
		handleFetchImage(imagePathWp, (v)=>open2ImageCb(v,extTp));
	}

	

	const updateViewCmp = async () => {
		if(data.imagePath ){
			updStore(qryKClient()+"_upd", data);
			updStore(qryKClient()+"_upd_bck", JSON.parse(JSON.stringify(data)));
			openImage(data.imagePath)
		}
		else{
			update()
		}
	}

	return (
		<div className="item_acc">
			<div className="_dsplFlx operation_item_box" >
				<div className="icon_revision"  onClick={openLinkCmp}>
					<Svg 
						name={data.inManualRevision ? "help" : data.comprobanteId ? "success":"alert"} 
						color={data.inManualRevision ? "var(--partial-success)" : data.comprobanteId? "var(--hrm_palette-success-fg)":"var(--hrm_palette-selected-nav-text)"}
					/>
				</div>
				<div className=" tr_bar_15 font_onm" >
					<NavLink to={{
							pathname: "/accounting-ledger" ,
							search: `?cId=${data.comprobanteId}`
						}}>
							{data?.comprobanteId }
					</NavLink>
				</div>
				<div className="_dsplFlx tr_bar_70" onClick={updateViewCmp}>
					<div className=" tr_bar_15" >
						{parseDateMMDDYYYY(data?.date*1)} 
					</div>
					<div className=" tr_bar_25 font_onm" style={{ color:data.movementType==="expense"?"var(--hrm_palette-selected-nav-text)": "var( --hrm_palette-blue-purple)"}}>
						{data?.title }
					</div>
					<div className=" tr_bar_45  font_onm" style={{marginLeft: 9}}>
					
						{data?.description }
						
					</div>
					<div className=" tr_bar_15 txt_al_r" style={{ color:data.movementType==="expense"?"var(--hrm_palette-selected-nav-text)": "var( --hrm_palette-blue-purple)"}}>
						{data?.amount }
					</div>
				</div>
				
				<div className="flexSpace"/>
				{data?.imagePath? 
				<div className="icon tr_bar_5" onClick={open2Image}>
					<Svg name={"image_outline"} color={"var(--partial-success)"}/>
				</div>
				:<div className="icon tr_bar_5" />
				}
				<div className="icon tr_bar_5" onClick={OpenDeleteAlert}>
					<Svg name={"outline_delete"} color={"#c62828"}/>
				</div>
				
			</div>
			
		</div>
	)
}
export default FeedfromMobileItem;